export const taskPrompts={technical:'TECHNICAL-BLOG.md',insight:'INDUSTRY-INSIGHT.md',review:'EXISTING-CONTENT-REVIEW.md',guide:'ENGINEERING-GUIDE.md',commercial:'COMMERCIAL-PAGE.md',translation:'TRANSLATION.md'};
