    const providerRequestId=String(response.headers?.['x-request-id']||response.headers?.['request-id']||'').slice(0,160);
    if(response.status!==200){let providerCode='';try{const error=JSON.parse(response.text).error;providerCode=String(error?.code||error?.type||'').slice(0,100).replaceAll(c.apiKey,'[redacted]');}catch{}throw new AIRequestError('AI服务返回HTTP '+response.status+(providerCode?'（'+providerCode+'）':''),'PROVIDER_HTTP',{httpStatus:response.status,providerCode,providerRequestId,retryable:response.status===429||response.status>=500});}
